; ---------------------------------------------------------------------
; RESIDENT: INT 17h printer hook
; ---------------------------------------------------------------------

; INT 17h HOOK  --  jmp [2D7Bh]   ([2D7Bh] เลือกโดย 2E28h จากตาราง 2D77h: 2D82h หรือ 2ED1h)
;   AH=60h / 61h  = คำสั่งส่วนตัวของ THAID: ตั้ง [32FAh] = 1 / 0 แล้วเรียก 32AAh (แปลงรหัสตัวอักษร)
;                    จากนั้น INT A8h  (ตัวขับพิมพ์ที่อยู่ในนี้เอง) แล้วล้าง AH
;   AH=00h = พิมพ์ 1 ตัว -> เรียกตัวกรอง [2DBFh] ก่อน แล้ว chain [272Ch] (INT 17h เดิม)
;   AH อื่น (สถานะ/init) -> chain ตรงๆ

L2D7D:                ; INT 17h handler (hooked)
2D7D  2eff267b2d       jmp word ptr cs:[0x2d7b]

L2D82:                ; INT 17h main path
2D82  80fc60           cmp ah, 0x60                 ; AH == 60h ?
2D85  740e             je 0x2d95
2D87  80fc61           cmp ah, 0x61                 ; AH == 61h ? ไม่ใช่ -> ไปเช็คว่า AH==0
2D8A  7517             jne 0x2da3
2D8C  2ec706fa320000   mov word ptr cs:[0x32fa], 0  ; AH=61h: [32FAh] = 0  (โหมดตัวอักษรแบบ 0)
2D93  eb07             jmp 0x2d9c
2D95  2ec706fa320100   mov word ptr cs:[0x32fa], 1  ; AH=60h: [32FAh] = 1  (โหมดแบบ 1 -- ใช้เลือกตารางแปลงที่ 32AAh)
2D9C  e80b05           call 0x32aa                  ; แปลงรหัสตัวอักษรใน AL ตามโหมด (ดู 32AAh)
2D9F  cda8             int 0xa8                     ; INT A8h = ตัวขับพิมพ์/ตัวแปลงของ THAID เอง
2DA1  32e4             xor ah, ah                   ; ล้าง AH
2DA3  84e4             test ah, ah                  ; AH == 0 (พิมพ์ตัวอักษร) ?
2DA5  7505             jne 0x2dac
2DA7  2eff16bf2d       call word ptr cs:[0x2dbf]    ; ใช่ -> ผ่านตัวกรอง/สถานะที่ [2DBFh]
2DAC  2eff2e2c27       ljmp cs:[0x272c]             ; ต่อไป INT 17h เดิมของ BIOS/DOS
2DB1  db  26h, 2Eh, 17h, 2Eh, 00h, 00h, 00h, 00h, 00h, 00h, 00h, 00h, B5h, 2Dh, C1h, 2Dh

L2DC1:                ; INT 17h filter idle state
2DC1  3c9b             cmp al, 0x9b                 ; สถานะ IDLE ของตัวกรอง: AL == 9Bh (นำหน้าลำดับพิเศษ) ?
2DC3  7401             je 0x2dc6
2DC5  c3               ret                          ; ไม่ใช่: return -> ตัวอักษรถูกส่งต่อไปเครื่องพิมพ์ตามปกติ
2DC6  2ec706bf2dcd2d   mov word ptr cs:[0x2dbf], 0x2dcd; ใช่: สลับ [2DBFh] = 2DCDh (สถานะรวบรวม)  แล้วตัวอักษรนี้ยังส่งต่อ

L2DCD:                ; INT 17h filter collect state
2DCD  44               inc sp                       ; สถานะ COLLECT: ทิ้ง return address (inc sp x2) = ตัวอักษรนี้ "ไม่ถูกส่ง" ไป chain
2DCE  44               inc sp
2DCF  56               push si
2DD0  2e8b36bd2d       mov si, word ptr cs:[0x2dbd] ; SI = พอยน์เตอร์เขียนในบัฟเฟอร์ [2DBDh] (เริ่ม 2DB5h)
2DD5  2e8904           mov word ptr cs:[si], ax     ; เก็บ AX ลงบัฟเฟอร์ (AH=0 ทำหน้าที่ตัวจบสตริง)
2DD8  2eff06bd2d       inc word ptr cs:[0x2dbd]     ; ขยับพอยน์เตอร์ 1 ไบต์
2DDD  5e               pop si
2DDE  50               push ax
2DDF  2eff36b12d       push word ptr cs:[0x2db1]
2DE4  2eff36b32d       push word ptr cs:[0x2db3]
2DE9  2eff163c0a       call word ptr cs:[0xa3c]     ; เรียกรูทีนภายนอกผ่าน [0A3Ch] (ตัวแปลงลำดับพิมพ์ ยังไม่ได้ตามไปดู)
2DEE  56               push si
2DEF  50               push ax
2DF0  beb52d           mov si, 0x2db5               ; SI = บัฟเฟอร์ 2DB5h : ไล่ส่งทีละไบต์จนเจอ 00
2DF3  2e8a04           mov al, byte ptr cs:[si]     ; AL = ไบต์ถัดไป; 0 = จบ
2DF6  84c0             test al, al
2DF8  741a             je 0x2e14
2DFA  32e4             xor ah, ah
2DFC  9c               pushf 
2DFD  2ef606300101     test byte ptr cs:[0x130], 1  ; bit0 ของ [130h] = ส่งผ่านตัวขับภายใน (2EDEh) แทน BIOS?
2E03  7407             je 0x2e0c
2E05  0e               push cs
2E06  e8d500           call 0x2ede                  ; far-call แบบ push cs + call: ไปตัวขับภายใน 2EDEh (ลงท้ายด้วย iret)
2E09  46               inc si
2E0A  ebe7             jmp 0x2df3
2E0C  2eff1e2c27       lcall cs:[0x272c]            ; ไม่ใช่: lcall INT 17h เดิม [272Ch] ส่งไบต์นี้
2E11  46               inc si
2E12  ebdf             jmp 0x2df3
2E14  58               pop ax                       ; จบ: เก็บกวาด stack
2E15  5e               pop si
2E16  58               pop ax
2E17  58               pop ax
2E18  2ec706bd2db52d   mov word ptr cs:[0x2dbd], 0x2db5; รีเซ็ต [2DBDh] = 2DB5h (ตัวเขียน)
2E1F  2ec706bf2dc12d   mov word ptr cs:[0x2dbf], 0x2dc1; รีเซ็ต [2DBFh] = 2DC1h (กลับสถานะ IDLE) -> iret
2E26  58               pop ax
2E27  cf               iret 

; เลือกตัวขับ INT 17h ตาม AL (0/1):  [130h] bit0 = AL ;  [2D7Bh] = [2D77h + 2*AL]
;   AL=0 -> 2D82h (ส่งผ่าน BIOS)   AL=1 -> 2ED1h (ตัวขับภายใน)
2E28  53               push bx
2E29  33db             xor bx, bx
2E2B  8ad8             mov bl, al
2E2D  d1e3             shl bx, 1
2E2F  2e80263001fe     and byte ptr cs:[0x130], 0xfe
2E35  2e08063001       or byte ptr cs:[0x130], al
2E3A  2e8b9f772d       mov bx, word ptr cs:[bx + 0x2d77]
2E3F  2e891e7b2d       mov word ptr cs:[0x2d7b], bx
2E44  5b               pop bx
2E45  c3               ret 

